mapper.select:
SELECT flows.flowDate AS date, SUM(flows.chargeAmount) AS chargeAmount, SUM(flows.exchangePaidAmount) AS exchangePaidAmount, SUM(flows.commissionAmount) AS commissionAmount, SUM(flows.auctionTradeAmount) AS auctionTradeAmount, SUM(flows.serviceTradeAmount) AS serviceTradeAmount FROM ( SELECT DATE(PT_CHG_ORD_UPDT_DT) AS flowDate, PT_CHG_ORD_AMT AS chargeAmount, 0 AS exchangePaidAmount, 0 AS commissionAmount, 0 AS auctionTradeAmount, 0 AS serviceTradeAmount FROM POINT_CHARGE_ORDER WHERE PT_CHG_ORD_STATUS_CD = 'PCOC0002' AND PT_CHG_ORD_UPDT_DT >= #{startAt} AND PT_CHG_ORD_UPDT_DT < #{endAt}
UNION ALL
SELECT DATE(PT_EXC_ORD_PROC_DT) AS flowDate, 0 AS chargeAmount, PT_EXC_ORD_AMT AS exchangePaidAmount, 0 AS commissionAmount, 0 AS auctionTradeAmount, 0 AS serviceTradeAmount FROM POINT_EXCHANGE_ORDER WHERE PT_EXC_ORD_STATUS_CD = 'PEOC0002' AND PT_EXC_ORD_PROC_DT >= #{startAt} AND PT_EXC_ORD_PROC_DT < #{endAt}
UNION ALL
SELECT DATE(PT_LDG_REG_DT) AS flowDate, 0 AS chargeAmount, 0 AS exchangePaidAmount, -PT_LDG_AMT AS commissionAmount, 0 AS auctionTradeAmount, 0 AS serviceTradeAmount FROM POINT_LEDGER WHERE PT_LDG_TYPE_CD = 'PTLC0014' AND PT_LDG_REG_DT >= #{startAt} AND PT_LDG_REG_DT < #{endAt}
UNION ALL
SELECT DATE(completed.completedAt) AS flowDate, 0 AS chargeAmount, 0 AS exchangePaidAmount, 0 AS commissionAmount, CASE WHEN t.TRD_TYPE_CD = 'TRDC0001' THEN t.TRD_AMT ELSE 0 END AS auctionTradeAmount, CASE WHEN t.TRD_TYPE_CD = 'TRDC0002' THEN t.TRD_AMT ELSE 0 END AS serviceTradeAmount FROM TRADE t JOIN ( SELECT TRD_SN, MAX(TRD_STS_HST_REG_DT) AS completedAt FROM TRADE_STATUS_HIST WHERE TRD_STS_HST_STATUS_CD = 'TRDC0006' GROUP BY TRD_SN ) completed ON completed.TRD_SN = t.TRD_SN WHERE t.TRD_STATUS_CD = 'TRDC0006' AND t.TRD_TYPE_CD IN ('TRDC0001', 'TRDC0002') AND completed.completedAt >= #{startAt} AND completed.completedAt < #{endAt} ) flows GROUP BY flows.flowDate ORDER BY flows.flowDate ASC
